from jsonb_to_recordset($examcontext$[{"question_id":"exam-ch34-v1-grammar-under","content_key":"[\"sentences\",\"The ball is directly below the box. It is _____ the box.\",\"under\",\"The ball is directly below the box. It is under the box.\",\"Place: under\",[\"above\",\"in\",\"on\",\"under\"],\"\",\"under\"]","pattern_key":"exam-grammar","title_th":"ดูตำแหน่งเทียบกับสิ่งอ้างอิง","rule_th":"หาสิ่งที่กำลังพูดถึงก่อน แล้วดูว่ามันอยู่ตรงไหนเมื่อเทียบกับกล่อง ไม่เลือกจากชื่อสิ่งของเพียงอย่างเดียว","clue_th":"ลูกบอลอยู่ต่ำกว่ากล่องและตรงกับกล่องในแนวดิ่ง ใช้ under","contrasts":[{"label_th":"รูปแบบแรก","text":"under the box"},{"label_th":"อีกตัวอย่าง","text":"on the box"}],"examples":["The ball is under the box.","The cat is under the chair."],"caution_th":null},{"question_id":"exam-ch34-v1-grammar-behind","content_key":"[\"sentences\",\"The box hides the ball at its back. It is _____ the box.\",\"behind\",\"The box hides the ball at its back. It is behind the box.\",\"Place: behind\",[\"behind\",\"in\",\"in front of\",\"on\"],\"\",\"behind\"]","pattern_key":"exam-grammar","title_th":"ดูตำแหน่งเทียบกับสิ่งอ้างอิง","rule_th":"หาสิ่งที่กำลังพูดถึงก่อน แล้วดูว่ามันอยู่ตรงไหนเมื่อเทียบกับกล่อง ไม่เลือกจากชื่อสิ่งของเพียงอย่างเดียว","clue_th":"กล่องบังลูกบอลไว้ แสดงว่าลูกบอลอยู่ด้านหลัง ใช้ behind","contrasts":[{"label_th":"รูปแบบแรก","text":"behind the box"},{"label_th":"อีกตัวอย่าง","text":"under the box"}],"examples":["The ball is behind the box.","The cat is behind the chair."],"caution_th":null},{"question_id":"exam-ch34-v1-grammar-in-front-of","content_key":"[\"sentences\",\"The ball blocks the front of the box. It is _____ the box.\",\"in front of\",\"The ball blocks the front of the box. It is in front of the box.\",\"Place: in front of\",[\"behind\",\"in\",\"in front of\",\"under\"],\"\",\"in front of\"]","pattern_key":"exam-grammar","title_th":"ดูตำแหน่งเทียบกับสิ่งอ้างอิง","rule_th":"หาสิ่งที่กำลังพูดถึงก่อน แล้วดูว่ามันอยู่ตรงไหนเมื่อเทียบกับกล่อง ไม่เลือกจากชื่อสิ่งของเพียงอย่างเดียว","clue_th":"ลูกบอลบังส่วนหน้าของกล่อง แสดงว่าลูกบอลอยู่ด้านหน้า ใช้ in front of","contrasts":[{"label_th":"รูปแบบแรก","text":"in front of the box"},{"label_th":"อีกตัวอย่าง","text":"under the box"}],"examples":["The ball is in front of the box.","The cat is in front of the chair."],"caution_th":null},{"question_id":"exam-ch34-v1-grammar-between","content_key":"[\"sentences\",\"There is a box on each side of the ball. It is _____ the boxes.\",\"between\",\"There is a box on each side of the ball. It is between the boxes.\",\"Place: between\",[\"behind\",\"between\",\"on\",\"under\"],\"\",\"between\"]","pattern_key":"exam-grammar","title_th":"ดูตำแหน่งเทียบกับสิ่งอ้างอิง","rule_th":"หาสิ่งที่กำลังพูดถึงก่อน แล้วดูว่ามันอยู่ตรงไหนเมื่อเทียบกับกล่อง ไม่เลือกจากชื่อสิ่งของเพียงอย่างเดียว","clue_th":"มีหนึ่งกล่องทางซ้ายและอีกกล่องทางขวา ลูกบอลอยู่ตรงกลาง ใช้ between","contrasts":[{"label_th":"รูปแบบแรก","text":"between the boxes"},{"label_th":"อีกตัวอย่าง","text":"under the box"}],"examples":["The ball is between the boxes.","The cat is between the chairs."],"caution_th":null},{"question_id":"exam-ch34-v1-grammar-beside","content_key":"[\"sentences\",\"The ball is at the side of the box. It is _____ the box.\",\"beside\",\"The ball is at the side of the box. It is beside the box.\",\"Place: beside\",[\"beside\",\"in\",\"on\",\"under\"],\"\",\"beside\"]","pattern_key":"exam-grammar","title_th":"ดูตำแหน่งเทียบกับสิ่งอ้างอิง","rule_th":"หาสิ่งที่กำลังพูดถึงก่อน แล้วดูว่ามันอยู่ตรงไหนเมื่อเทียบกับกล่อง ไม่เลือกจากชื่อสิ่งของเพียงอย่างเดียว","clue_th":"ลูกบอลอยู่ข้างกล่องในระดับเดียวกัน ใช้ beside ซึ่งมีความหมายใกล้เคียง next to","contrasts":[{"label_th":"รูปแบบแรก","text":"beside the box"},{"label_th":"อีกตัวอย่าง","text":"under the box"}],"examples":["The ball is beside the box.","The cat is beside the chair."],"caution_th":null},{"question_id":"exam-ch34-v1-grammar-above","content_key":"[\"sentences\",\"The ball is higher than the box without touching